#!/usr/bin/env bash
# post-deploy-verify.sh — run AFTER deploy-worker-fix.sh succeeds.
# Repackages (in case /tmp was wiped) and runs:
#   A. the e2e upload test (upload -> OSS -> confirm -> worker -> ready)
#   B. the admin password hash migration (ADMIN_PASSWORD_HASH in backend/.env)
set -e
mkdir -p /tmp/wmp-files
base64 -d > /tmp/wmp-files/e2e-upload-test.sh <<'B64_E2E'

B64_E2E
base64 -d > /tmp/wmp-files/admin-hash-to-env.sh <<'B64_HASH'

B64_HASH
chmod +x /tmp/wmp-files/*.sh

echo "================ A. e2e upload test ================"
bash /tmp/wmp-files/e2e-upload-test.sh

echo ""
echo "============ B. admin password -> hash only ============"
bash /tmp/wmp-files/admin-hash-to-env.sh
echo ""
echo "ALL DONE — uploads should now reach 'ready'; password hash stored in backend/.env"